// Part: room: east upper corridor and wing passage (room 21, upper floor y11..16, box x52..68 z51..60).
// Upstairs passage from the hall (west door x51 z51..52) east to the master bedroom and master bath doors (z50),
// the wing passage (x52..53 z53..60, opening z61) and the bedroom 5 and bath doors (z53 / x54 z57).
// Lanes kept clear: z52 is the through lane (carpeted), z51 x52..55 and x66..67 are the door first cells.
// Furniture stands on the north wall (z51) between x56 and x68: a linen run of barrels and chests, a console
// (dark oak fences with a top slab) carrying a potted plant and a standing lantern. Hanging lanterns down the lane
// and in the wing passage. Chimney cells x61..62 z56..57 are left alone (roof part).
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const X0 = 52;
const Z0 = 51;
const W = 17; // x52..68
const ROWS = 10; // z51..60

// one row of W cells from a sparse map {x: char}
function row(cells) {
  const r = Array(W).fill(" ");
  for (const [x, ch] of Object.entries(cells)) r[Number(x) - X0] = ch;
  return r.join("");
}

// rows z51..60 from a sparse map {z: {x: char}}
function rows(byZ) {
  return Array.from({ length: ROWS }, (_, i) => row(byZ[Z0 + i] ?? {}));
}

export function build(g) {
  // floor furniture (y11): linen run and console on the north wall, runner carpet down the lane
  layers(g, [X0, 11, Z0], {
    b: "barrel",
    c: ["chest", { facing: "south" }],
    f: "dark_oak_fence",
    r: "red_carpet",
  }, [rows({
    51: { 56: "b", 57: "c", 58: "b", 59: "f", 60: "f", 61: "c", 62: "b", 68: "b" },
    52: Object.fromEntries(Array.from({ length: 14 }, (_, i) => [X0 + 2 + i, "r"])), // x54..67
  })]);

  // console top (y12): top slabs on the fence posts
  layers(g, [X0, 12, Z0], {
    t: ["dark_oak_slab", { type: "top" }],
  }, [rows({ 51: { 59: "t", 60: "t" } })]);

  // console dressing (y13): a potted plant and a standing lantern on the top
  layers(g, [X0, 13, Z0], {
    p: "flower_pot",
    l: ["lantern", { hanging: "false" }],
  }, [rows({ 51: { 59: "p", 60: "l" } })]);

  // hanging lanterns (y16) under the plate: down the lane, and in the wing passage
  layers(g, [X0, 16, Z0], {
    h: ["lantern", { hanging: "true" }],
  }, [rows({
    52: { 53: "h", 58: "h", 63: "h", 67: "h" },
    55: { 53: "h" },
    59: { 53: "h" },
  })]);

  return { placed: "room 21" };
}

