1	// Part: mansion shell. Brick base, white walls with quartz courses, floors, partitions, doorways, openings (air), pilasters, vault cove.
2	import { B, carve } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
3	import { vaultCove, CHIMNEYS } from "../vocab.mjs";
4	
5	const WALL = "white_concrete", Q = "smooth_quartz";
6	const STACKS = CHIMNEYS.map(([x, z]) => [x, z, x + 1, z + 1]);
7	
8	export function build(g) {
9	  const fill = (a, b, blk) => g.fill(a, b, blk);
10	  const open = (x0, y0, z0, x1, y1, z1) => carve(g, [x0, y0, z0], [x1, y1, z1]);
